"""Frozen supplementary summaries; never modify the official measurement."""
import json
import random
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parent
SEED = 202610111
DRAWS = 10000


def quantile(xs, p):
    ys = sorted(xs)
    z = (len(ys) - 1) * p
    lo = int(z)
    hi = min(lo + 1, len(ys) - 1)
    return ys[lo] + (ys[hi] - ys[lo]) * (z - lo)


def interval(xs):
    return [round(quantile(xs, .025), 5), round(quantile(xs, .975), 5)]


if __name__ == '__main__':
    measurement = json.loads((ROOT / 'rate-run-result.json').read_text())
    assert measurement is not None, 'No measurement: report abort instead.'
    aid = measurement['attempt_id']
    raw = json.loads((ROOT / f'rate-runspec.json.attempt-{aid}.cells.json').read_text())
    print('Cell receipt envelope:', list(raw) if isinstance(raw, dict) else 'list')
    cells = raw['rows'] if isinstance(raw, dict) else raw
    items = {i['id']: i for i in json.loads((ROOT / 'rate-items-execution.json').read_text()) if not i.get('calibration')}
    by_item = {iid: {} for iid in items}
    counts = {}
    for row in cells:
        iid = row['item_id']
        assert iid in items and row['arm'] not in by_item[iid]
        assert row['answer'] and row['correct'] is not None, 'Incomplete worlds: retain official result; no unplanned supplementary imputation.'
        by_item[iid][row['arm']] = int(row['correct'])
        for key in [('overall', 'all'), ('form', items[iid]['settlement_stratum']),
                    ('reader_form', row['reader'] + ' / ' + items[iid]['settlement_stratum']),
                    ('frame', items[iid]['semantic_frame'])]:
            stats = counts.setdefault(key, {'english': [0, 0], 'ainglish': [0, 0]})
            stats[row['arm']][0] += int(row['correct'])
            stats[row['arm']][1] += 1
    assert len(cells) == 256 and all(set(v) == {'english', 'ainglish'} for v in by_item.values())
    summaries = []
    for (kind, label), arms in counts.items():
        rates = {a: x[0] / x[1] for a, x in arms.items()}
        summaries.append({'kind': kind, 'label': label, 'correct_total': arms, 'absolute_accuracy': rates,
                          'delta_pp': 100 * (rates['ainglish'] - rates['english'])})
    differences = {iid: arms['ainglish'] - arms['english'] for iid, arms in by_item.items()}
    form_ids = {form: [i for i in items if items[i]['settlement_stratum'] == form] for form in ['rate', 'stock']}
    rng = random.Random(SEED)
    bootstrap = {}
    for method in ['item_within_form', 'semantic_frame_cluster_within_form']:
        draws = {'rate': [], 'stock': [], 'overall': []}
        for _ in range(DRAWS):
            sampled = {}
            for form, ids in form_ids.items():
                if method == 'item_within_form':
                    selected = rng.choices(ids, k=len(ids))
                else:
                    frames = sorted({items[i]['semantic_frame'] for i in ids})
                    selected = [i for f in rng.choices(frames, k=len(frames)) for i in ids if items[i]['semantic_frame'] == f]
                sampled[form] = 100 * sum(differences[i] for i in selected) / len(selected)
                draws[form].append(sampled[form])
            draws['overall'].append((sampled['rate'] + sampled['stock']) / 2)
        bootstrap[method] = {form: interval(values) for form, values in draws.items()}
    result = {
        'attempt_id': aid, 'official_result_unchanged': {k: measurement.get(k) for k in ['value', 'value_lo', 'value_hi', 'arms', 'stratum_results']},
        'summaries': summaries,
        'supplemental_bootstrap': {'draws': DRAWS, 'seed': SEED, 'rng': 'Python random.Random MT19937; methods/forms in listed order',
                                    'quantiles': 'linear interpolation, 0.025 and 0.975', 'intervals_pp': bootstrap},
        'limits': ['Two fixed, quantised current-reader configurations; not model-population uncertainty.',
                   'Public author bank, 128 worlds in 16 recurring semantic frames; not independent confirmation.',
                   'Supplemental intervals are report-only and do not replace attested official bounds or current admission rules.',
                   'Cold-model performance does not predict performance after Ainglish is incorporated into training or tokenisers.'],
    }
    (ROOT / 'rate-analysis.json').write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n')
    print(json.dumps({k: v for k, v in result.items() if k != 'summaries'}, indent=2))
    print(json.dumps([x for x in summaries if x['kind'] != 'frame'], indent=2))
